 * type: the parts of a numeral's dispatch that its default's type does
 * not fix (inRange).
 */
private static FType rangeKey(FValue v) {
    int inf = infiniteAt(((Numeral) v).site());
    if (inf > 0) return inf == 1 ? FTypeVoid.ONLY : FTypeRange.ONLY;
